<template><div class="app-container"><el-form :model="query" inline><el-form-item label="外管账号"><el-input v-model="query.loginName" clearable/></el-form-item><el-form-item label="所属SA"><el-input v-model="query.superAdminName" clearable/></el-form-item><el-form-item label="操作类型"><el-select v-model="query.operationType" clearable><el-option v-for="item in types" :key="item.value" :label="item.label" :value="item.value"/></el-select></el-form-item><el-button type="primary" @click="load">查询</el-button></el-form><el-table :data="rows" v-loading="loading" border><el-table-column prop="createTime" label="时间" min-width="170"/><el-table-column prop="loginName" label="外管"/><el-table-column prop="roleCode" label="角色"/><el-table-column prop="superAdminName" label="所属SA"/><el-table-column prop="operationType" label="操作类型"/><el-table-column prop="target" label="对象"/><el-table-column prop="content" label="内容" min-width="220"/></el-table><pagination v-show="total>0" v-model:page="query.pageNum" v-model:limit="query.pageSize" :total="total" @pagination="load"/></div></template>
<script setup>import { listExternalOperationLogs } from '@/api/external/manager'; const types=[{value:'BAN',label:'执行封禁'},{value:'UNBAN',label:'解除封禁'},{value:'CREATE_SUBORDINATE',label:'新增下级'},{value:'CREATE_GUILD',label:'新建公会'},{value:'ISSUE_GIFT',label:'赠送礼包'},{value:'ASSIGN_CHAT_NO',label:'分配靓号'}];const loading=ref(false),rows=ref([]),total=ref(0),query=reactive({pageNum:1,pageSize:10,loginName:'',superAdminName:'',operationType:''});async function load(){loading.value=true;try{const r=await listExternalOperationLogs(query);rows.value=r.rows;total.value=r.total}finally{loading.value=false}}load()</script>
